type VoidEarlierCodesParams struct {
	Now       time.Time
	OrgID     int64
	ContactID pgtype.Int8
	Keep      int64
}

// VoidEarlierCodes voids the codes of a contact asked for before keep that are neither used nor void, which keep
// replaces once the gateway accepted it.
func (q *Queries) VoidEarlierCodes(ctx context.Context, arg VoidEarlierCodesParams) (int64, error) {
	result, err := q.db.Exec(ctx, voidEarlierCodes,
		arg.Now,
		arg.OrgID,
		arg.ContactID,
		arg.Keep,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
